def _diff(expected, actual):
    """
    Process the diff of two objects.
    """
    if isinstance(expected, (list, tuple)):
        if len(expected) != len(actual):
            return f"Expected {len(expected)} items, got {len(actual)}"

        for i in range(len(expected)):
            diff = _diff(expected[i], actual[i])
            if diff:
                return f"Index {i}: {diff}"

    if isinstance(expected, dict):
        diff = {}
        for key in expected:
            if key not in actual:
                diff[key] = "missing"
                continue

            diff[key] = _diff(expected[key], actual[key])

        return ", ".join(f"{key}: {value}" for key, value in diff.items())

    if expected != actual:
        return f"Expected {_process_value(expected)}, got {_process_value(actual)}"

    return ""


def _assert_diff(expected, actual):
    """
    Process the diff of two objects and raise an AssertionError if they are not equal.
    """
    diff = _diff(expected, actual)
    if diff:
        raise AssertionError(diff)


